    grid = [['#' for _ in range(w)] for _ in range(h)]

    def is_valid(x, y):
        return 0 <= x < h and 0 <= y < w

    def dfs(x, y, color):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if grid[cx][cy] != '#':
                continue
            grid[cx][cy] = color
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if is_valid(nx, ny) and grid[nx][ny] == '#':
                    stack.append((nx, ny))

    # Place A white components
    for _ in range(A):
        placed = False
        while not placed:
            x, y = random.randint(0, h-1), random.randint(0, w-1)
            if grid[x][y] == '#':
                dfs(x, y, '.')
                placed = True

    # Place B black components
